    public void RefreshShortcutTooltips(){if(controlBody is not Grid root)return;var tools=root.Children.OfType<System.Windows.Controls.Primitives.UniformGrid>().FirstOrDefault();if(tools==null)return;RefreshToolButtonTexts(tools);var shortcutLabel=Localization.T("快捷鍵",service.State.Language);var unsetLabel=Localization.T("未設定（可在設定頁配置）",service.State.Language);foreach(var button in tools.Children.OfType<System.Windows.Controls.Button>()){var key=button.Tag?.ToString();if(string.IsNullOrEmpty(key))continue;var shortcut=service.State.Hotkeys.GetValueOrDefault(key,"");var label=ToolButtonText(key);button.ToolTip=string.IsNullOrWhiteSpace(shortcut)?$"{label}\n{shortcutLabel}：{unsetLabel}":$"{label}\n{shortcutLabel}：{shortcut}";}ShortcutHint.Text="";ShortcutHint.Visibility=Visibility.Collapsed;}
