    public void RefreshFeatures(){if(controlBody is not Grid root)return;var tools=root.Children.OfType<System.Windows.Controls.Primitives.UniformGrid>().FirstOrDefault();if(tools==null)return;ApplyToolOrder();foreach(var button in tools.Children.OfType<System.Windows.Controls.Button>()){var key=button.Tag?.ToString()??"";var userVisible=!service.State.ToolButtonVisibility.TryGetValue(key,out var visible)||visible;button.Visibility=userVisible?Visibility.Visible:Visibility.Collapsed;}AdaptToolGrid();}
