    void ToolGrid_MouseLeftButtonDown(object sender,MouseButtonEventArgs e){toolDragStart=e.GetPosition(this);toolDragButton=VisualTreeUtils.FindParent<Button>(e.OriginalSource as DependencyObject);}
    void ToolGrid_MouseMove(object sender,MouseEventArgs e){if(e.LeftButton!=MouseButtonState.Pressed||toolDragButton==null)return;var p=e.GetPosition(this);if(Math.Abs(p.X-toolDragStart.X)<6&&Math.Abs(p.Y-toolDragStart.Y)<6)return;DragDrop.DoDragDrop(toolDragButton,toolDragButton.Tag?.ToString()??"",DragDropEffects.Move);}
