    public void ApplyPreferences(){var state=service.State;var dark=state.Theme=="Dark";var honey=state.Theme=="Honey";var alpha=(byte)Math.Clamp(state.WidgetOpacity*255,0,255);var uniform=dark?System.Windows.Media.Color.FromArgb(alpha,13,19,33):honey?System.Windows.Media.Color.FromArgb(alpha,255,244,222):System.Windows.Media.Color.FromArgb(alpha,245,247,250);var panelAlpha=(byte)Math.Clamp(state.WidgetOpacity*36,0,48);var panel=System.Windows.Media.Color.FromArgb(panelAlpha,255,255,255);Background=System.Windows.Media.Brushes.Transparent;if(controlRoot!=null){controlRoot.Background=new System.Windows.Media.SolidColorBrush(uniform);controlRoot.CornerRadius=new CornerRadius(state.CornerRadius);}if(controlBody!=null)controlBody.Background=System.Windows.Media.Brushes.Transparent;Foreground=ContrastHelper.TextFor(new System.Windows.Media.SolidColorBrush(uniform),dark?System.Windows.Media.Brushes.White:new System.Windows.Media.SolidColorBrush(System.Windows.Media.Color.FromRgb(13,19,33)));Resources["ControlPrimary"]=Foreground;Resources["ControlSecondary"]=new System.Windows.Media.SolidColorBrush(dark?System.Windows.Media.Color.FromRgb(198,205,218):System.Windows.Media.Color.FromRgb(107,114,128));Resources["ControlSurface"]=new System.Windows.Media.SolidColorBrush(panel);Resources["ControlLine"]=new System.Windows.Media.SolidColorBrush(System.Windows.Media.Color.FromArgb(dark?(byte)54:(byte)34,255,255,255));FontSize=service.InterfaceFontSize();Localization.ApplyFont(this,service.InterfaceFontFamily(),service.InterfaceFontSize());if(System.Windows.PresentationSource.FromVisual(this)!=null)AcrylicHelper.Apply(this,state.Theme=="Acrylic",state.WidgetOpacity,dark);WindowRegionHelper.StyleCaptionButtons(this);ApplyBottomButtonIcons();ApplyCaptureButtonColor(dark);}
